import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";

const root = "/workspaces/FluidFramework/rust-service/measurements/refresh-92ecf30";
const read = (file) => JSON.parse(fs.readFileSync(path.join(root, file), "utf8"));
const statistics = (values) => {
	assert(values.every(Number.isFinite));
	const sorted = values.toSorted((left, right) => left - right);
	const count = sorted.length;
	const mean = sorted.reduce((sum, value) => sum + value, 0) / count;
	return {
		count,
		minimum: sorted[0],
		median: (sorted[Math.floor((count - 1) / 2)] + sorted[Math.floor(count / 2)]) / 2,
		maximum: sorted[count - 1],
		p95: sorted[Math.ceil(count * 0.95) - 1],
		sampleStandardDeviation: count > 1 ? Math.sqrt(sorted.reduce((sum, value) => sum + (value - mean) ** 2, 0) / (count - 1)) : null,
	};
};
const metrics = (row) => {
	const workers = row.workers ?? [];
	const configuration = row.configuration;
	return {
		directory: row.directory,
		configuration,
		status: row.status,
		passed: row.sustainable === true,
		error: row.error,
		delivered: row.deliveredOperationsPerSecond,
		payloadMiB: row.payloadMiBPerSecond,
		cpu: row.serviceCpuPercent,
		rss: row.serviceMeanRssMiB,
		peakRss: row.servicePeakRssMiB,
		p95: workers.length ? Math.max(...workers.map(worker => worker.latencyMilliseconds.p95 ?? 0)) : null,
		generatorCpu: workers.reduce((sum, worker) => sum + worker.generatorCpuSeconds, 0),
		maxGeneratorCpu: workers.length ? Math.max(...workers.map(worker => worker.generatorCpuSeconds)) : null,
		maxLag: workers.length ? Math.max(...workers.map(worker => worker.maxScheduleLagMilliseconds)) : null,
		pending: workers.reduce((sum, worker) => sum + worker.pendingAtEnd, 0),
		missing: workers.reduce((sum, worker) => sum + worker.missing, 0),
		errors: workers.flatMap(worker => worker.errors),
		backlogQuarterMeans: workers.map(worker => Array.from({ length: 4 }, (_, quarter) => {
			const samples = worker.backlog.filter(sample => sample.seconds >= configuration.warmupSeconds + quarter * configuration.seconds / 4 && sample.seconds < configuration.warmupSeconds + (quarter + 1) * configuration.seconds / 4);
			return samples.length ? samples.reduce((sum, sample) => sum + sample.pending, 0) / samples.length : null;
		})),
	};
};
const campaigns = {};
for (const name of ["repeat", "repeat-corrected", "native-repeat", ...["storage", "refine", "final"].flatMap(stage => [1, 4, 8].map(cores => `${stage}-${cores}`))]) {
	const manifest = read(`${name}/cells/manifest.json`);
	const rows = read(`${name}/cells/results.json`);
	assert.equal(rows.length, manifest.cells.length);
	for (const [index, row] of rows.entries()) {
		assert.deepEqual(row.configuration, manifest.cells[index]);
		const { directory, exitCode, ...raw } = row;
		assert.deepEqual(raw, read(`${name}/cells/${directory}/result.json`));
		assert.equal(manifest.commit, "92ecf30f4a7d17db882cc39e7c60d8d19c1042ba");
	}
	campaigns[name] = { run: read(`${name}/run.json`), manifest, samples: rows.map(metrics) };
}
const repeated = {};
for (const name of ["repeat-corrected", "native-repeat"]) {
	repeated[name] = Object.entries(Object.groupBy(campaigns[name].samples, row => JSON.stringify([row.configuration.backend, row.configuration.generator ?? "node", row.configuration.transport ?? "default", row.configuration.payloadBytes, row.configuration.cores, row.configuration.rate]))).map(([key, rows]) => ({
		key: JSON.parse(key),
		passed: rows.filter(row => row.passed).length,
		metrics: Object.fromEntries(["delivered", "payloadMiB", "cpu", "rss", "peakRss", "p95", "generatorCpu", "maxGeneratorCpu", "maxLag", "pending"].map(field => [field, statistics(rows.map(row => row[field]))])),
	}));
}
const browser = Object.fromEntries(fs.readdirSync(path.join(root, "browser/results")).map(file => [file, read(`browser/results/${file}`)]));
const midpoint = metrics(read("buffered-midpoint-corrected/cell/result.json"));
const storage = [...Object.entries(campaigns).filter(([name]) => /^(storage|refine|final)-/.test(name)).flatMap(([campaign, value]) => value.samples.map(row => ({ campaign, ...row }))), { campaign: "buffered-midpoint-corrected", ...midpoint }];
const summary = { revision: "92ecf30f4a7d17db882cc39e7c60d8d19c1042ba", analyzedAt: new Date().toISOString(), analysisSource: fs.readFileSync(import.meta.filename, "utf8"), campaigns, repeated, browser, storage, midpointRun: read("buffered-midpoint-corrected/run.json"), validationLogs: fs.readdirSync("/tmp/sea-refresh-92ecf30-validation").map(file => ({ file, sha256: createHash("sha256").update(fs.readFileSync(`/tmp/sea-refresh-92ecf30-validation/${file}`)).digest("hex") })) };
fs.writeFileSync(path.join(root, "summary.json"), `${JSON.stringify(summary, null, 2)}\n`);
const format = (value, digits = 2) => value.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
for (const [name, groups] of Object.entries(repeated)) {
	console.log(name);
	for (const group of groups) {
		const values = group.metrics;
		console.log(`| ${group.key.join(" / ")} | ${group.passed}/10 | ${format(values.delivered.median)} (${format(values.delivered.minimum)}-${format(values.delivered.maximum)}) | ${format(values.payloadMiB.median, 4)} | ${format(values.cpu.median)} | ${format(values.rss.median)} (${format(values.rss.minimum)}-${format(values.rss.maximum)}) | ${format(values.p95.median)} [${format(values.p95.minimum)}-${format(values.p95.maximum)}] | ${format(values.generatorCpu.median)} |`);
	}
}
console.log("storage totals", storage.length, "passes", storage.filter(row => row.passed).length, "startup failures", storage.filter(row => row.status === "failed").length);
for (const [key, rows] of Object.entries(Object.groupBy(storage, row => JSON.stringify([row.configuration.payloadBytes, row.configuration.cores, row.configuration.storage ?? "tinylicious"])))) {
	const passing = rows.filter(row => row.passed).toSorted((left, right) => right.configuration.rate - left.configuration.rate)[0];
	const failing = rows.filter(row => !row.passed && row.status !== "failed" && row.configuration.rate > (passing?.configuration.rate ?? 0)).toSorted((left, right) => left.configuration.rate - right.configuration.rate)[0];
	console.log(key, "pass", passing?.configuration.rate, "fail", failing?.configuration.rate, "details", JSON.stringify(passing));
}
console.log("repeat limits", JSON.stringify(Object.fromEntries(["repeat-corrected", "native-repeat"].map(name => [name, { maxGeneratorCpu: Math.max(...campaigns[name].samples.map(row => row.maxGeneratorCpu)), maxPending: Math.max(...campaigns[name].samples.map(row => row.pending)), errors: campaigns[name].samples.flatMap(row => row.errors).length, missing: campaigns[name].samples.reduce((sum, row) => sum + row.missing, 0) }]))));
